package com.bank.sorting;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BubbleSortDemo {

    private static final Logger log = Logger.getLogger(BubbleSortDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BigDecimal[] balances = {
            new BigDecimal("1000000"), new BigDecimal("250000"),
            new BigDecimal("50000"),   new BigDecimal("300000")
        };

        log.info(() -> "Before: " + Arrays.toString(balances));
        new BubbleSorter().sortAscending(balances);
        log.info(() -> "After:  " + Arrays.toString(balances));
    }
}

// ─── Would be in service/BubbleSorter.java in a real project ───
class BubbleSorter {

    private static final Logger log = Logger.getLogger(BubbleSorter.class.getName());

    // Sort ascending in place; log passes and swaps.
    void sortAscending(BigDecimal[] arr) {
        int n = arr.length;
        for (int pass = 0; pass < n - 1; pass++) {
            boolean swapped = false;                 // early-exit optimisation
            // Tail of length 'pass' is already sorted, so shrink the inner loop.
            for (int j = 0; j < n - 1 - pass; j++) {
                if (arr[j].compareTo(arr[j + 1]) > 0) {
                    swap(arr, j, j + 1);
                    swapped = true;
                    final int jj = j;
                    log.fine(() -> "  swap index " + jj + " and " + (jj + 1));
                }
            }
            final int p = pass;
            log.info(() -> "After pass " + (p + 1) + ": " + java.util.Arrays.toString(arr));
            if (!swapped) {                          // no swaps → already sorted
                log.info("No swaps this pass — array is sorted, exiting early.");
                break;
            }
        }
    }

    private void swap(BigDecimal[] arr, int i, int j) {
        BigDecimal temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
